const R = $json.valueRanges || [];
const pick = (n) => (R.find(x => String(x.range||'').indexOf(n) === 0) || {}).values || [];
const crit = pick('INVESTOR_CRITERIA');
const inv  = pick('INVESTORS!');
if (!crit.length || !inv.length) throw new Error('Read failed');

const g = (row,i) => (row && row[i] != null) ? String(row[i]).trim() : '';

// Rows deliberately excluded: researched as NOT investors.
const EXCLUDE = { '233':'MK Ventures - cannot confirm it is an investor', '251':'Diadem - deal-flow platform, not a fund', '269':'Seedflex - a company raising its own Series A' };

const data = [], flipped = [], excluded = [], untouched = [];

for (let i = 1; i < crit.length; i++) {
  const c = crit[i];
  const critRow = i + 1;
  const key = g(c,0);
  if (!key || !g(c,1)) continue;
  const n = parseInt(key, 10);
  const ivRow = (n > 1 && n <= inv.length) ? inv[n-1] : null;
  if (!ivRow || !g(ivRow,0)) continue;
  const name = g(ivRow,0);

  const st = g(c,3).toUpperCase();
  const cf = g(c,4).toUpperCase();
  const isHeld = (cf === 'PENDING') || (st === 'HOLD');
  if (!isHeld) continue;

  if (g(ivRow,9)) { untouched.push(n + ' ' + name + ' :: do_not_contact'); continue; }
  if (EXCLUDE[String(n)]) { excluded.push(n + ' ' + name + ' :: ' + EXCLUDE[String(n)]); continue; }

  const thesis = g(c,21);
  if (!thesis) { untouched.push(n + ' ' + name + ' :: no thesis_summary'); continue; }
  if (!g(ivRow,2)) { untouched.push(n + ' ' + name + ' :: no email'); continue; }

  const willMatch = (g(c,6).toUpperCase() === 'AGNOSTIC') || !!g(c,7);

  const changes = [];
  if (cf === 'PENDING') { data.push({ range: 'INVESTOR_CRITERIA!E' + critRow, values: [['USER']] }); changes.push('confirmed PENDING->USER'); }
  if (st === 'HOLD')    { data.push({ range: 'INVESTOR_CRITERIA!D' + critRow, values: [['ACTIVE']] }); changes.push('status HOLD->ACTIVE'); }
  if (!g(c,25))         { data.push({ range: 'INVESTOR_CRITERIA!Z' + critRow, values: [['2026-09-23: confirmed on Aditya’s instruction after thesis research; if the thesis proves wrong, capture the pass reason and correct.']] }); changes.push('rule_notes'); }

  flipped.push({ row: n, investor: name.slice(0,34), was: st + '/' + cf, changes: changes, will_match_deals: willMatch });
}

if (!data.length) throw new Error('Nothing to flip');
if (data.length > 250) throw new Error('Guard: refusing ' + data.length + ' cells (cap 250)');

return [{ json: { body: { valueInputOption: 'RAW', data: data }, cells: data.length,
                  rows: flipped.length,
                  going_live_now: flipped.filter(f => f.will_match_deals).length,
                  confirmed_but_no_sector_codes: flipped.filter(f => !f.will_match_deals).length,
                  flipped: flipped, excluded: excluded, untouched: untouched } }];

const c = $('Compute').first().json;
const w = $json;
return [{ json: { updatedCells: w.totalUpdatedCells != null ? w.totalUpdatedCells : null,
                  planned_cells: c.cells, rows: c.rows,
                  going_live_now: c.going_live_now,
                  confirmed_but_no_sector_codes: c.confirmed_but_no_sector_codes,
                  flipped: c.flipped, excluded: c.excluded, untouched: c.untouched } }];
